import{_ as a,a as t,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第二册：实践与进步 · Lesson 53 Hot snake","description":"学习 被动语态与信息重点，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 53 Hot snake","description":"学习 被动语态与信息重点，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 被动语态与信息重点，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 52 A pretty carpet","link":"/life/english/new-concept/book-2/unit-03/lesson-052"},"next":{"text":"第二册：实践与进步 · Lesson 54 Sticky fingers","link":"/life/english/new-concept/book-2/unit-03/lesson-054"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 52 A pretty carpet","link":"/life/english/new-concept/book-2/unit-03/lesson-052"},"next":{"text":"第二册：实践与进步 · Lesson 54 Sticky fingers","link":"/life/english/new-concept/book-2/unit-03/lesson-054"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-03/lesson-053.md","filePath":"life/english/new-concept/book-2/unit-03/lesson-053.md"}'),o={name:"life/english/new-concept/book-2/unit-03/lesson-053.md"};function s(r,e,l,d,c,h){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第二册-实践与进步-·-lesson-53-hot-snake" tabindex="-1">第二册：实践与进步 · Lesson 53 Hot snake <a class="header-anchor" href="#第二册-实践与进步-·-lesson-53-hot-snake" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 53 Hot snake&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>电线附近的异常引起短路，调查必须分清发现的时间与故障发生的时间；练习原因和被动。本课的语言观察是：was caused by 指向原因，但只有调查结果支持时才能这样断言；may have been caused by 则保留不确定性，语气不同。完成学习后，请写一份非技术故障说明，交代确认原因、发现位置和恢复条件。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>wire</td><td>/ˈwaɪə/</td><td>n.</td><td>电线</td><td>a damaged wire</td></tr><tr><td>spark</td><td>/spɑːk/</td><td>n.</td><td>火花</td><td>an electric spark</td></tr><tr><td>electricity</td><td>/ɪˌlekˈtrɪsəti/</td><td>n.</td><td>电</td><td>save electricity</td></tr><tr><td>cause</td><td>/kɔːz/</td><td>v.</td><td>导致</td><td>cause a fire</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>cut off the power — 切断电源</li><li>find the cause of — 找出……的原因</li></ul><h2 id="语法讲解-被动语态与信息重点" tabindex="-1">语法讲解：被动语态与信息重点 <a class="header-anchor" href="#语法讲解-被动语态与信息重点" aria-label="Permalink to &quot;语法讲解：被动语态与信息重点&quot;">​</a></h2><p>被动语态由相应时态的 be 加过去分词构成，把动作的承受者放在主语位置。时态变化主要体现在 be 上，过去分词本身不随主语改变。只有可以带宾语的相关用法才能形成通常的被动句，happen、arrive 等不及物动词不能照搬。执行者未知、不重要或已经显然时可以省略 by 短语；需要追责或形成对比时则应保留。本课应用：was caused by 指向原因，但只有调查结果支持时才能这样断言；may have been caused by 则保留不确定性，语气不同。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The power failure was caused by a damaged wire.</p></blockquote><p>这次停电是由一根损坏的电线引起的。</p><p>failure 为单数主语，was caused 是过去被动，by 引出原因；damaged 是过去分词作定语。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>caused from 不合常见搭配；被动原因用 caused by。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>区分 wire 与 fire 的首音，朗读 was caused by 时保留 caused 的 /zd/。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The power failure was caused by a damaged wire. An engineer found it behind a panel. The building remained closed until the repair was complete.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一份非技术故障说明，交代确认原因、发现位置和恢复条件。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：failure 为单数主语，was caused 是过去被动，by 引出原因；damaged 是过去分词作定语。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：caused from 不合常见搭配；被动原因用 caused by。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 by/from：The failure was caused ___ a damaged wire.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> by</p><p><strong>解析：</strong> be caused by 引出导致事件的原因。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>修理完成前大楼是否开放？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> No. It remained closed.</p><p><strong>解析：</strong> until 标明关闭状态持续的终点。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将 A damaged wire caused the failure 改为被动句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The failure was caused by a damaged wire.</p><p><strong>解析：</strong> 将受影响的事件前置，保留原因。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：被动语态与信息重点。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-03/lesson-052">上一课</a> · <a href="/life/english/new-concept/book-2/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-03/lesson-054">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(o,[["render",s]]);export{p as __pageData,b as default};
